void CTCPhysicsStandard::PerformForceUpdates()
{
    if (GetFeelsAirResistance()) {
        float keep = 1.0f - GetAirResistance();
        Velocity.X *= keep;
        Velocity.Y *= keep;
        Velocity.Z *= keep;
