    if (GetFeelsGravity()) {
        if (!IsOnGround() || GetWorldMap()->GetGroundFaceNormalAt(Position).Z < 0.98f
            || Velocity.GetLengthSquared() > g_epsilon_0129ba3c * g_epsilon_0129ba3c)
            ApplyAcceleration(C3DVector(0.0f, 0.0f, -0.12f));
    }
